def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []
    for word in words:
        # Sort the characters only if the word is not just spaces
        if word.strip():
            ordered_words.append(''.join(sorted(word)))
        else:
            ordered_words.append(word)  # Preserve spaces
    return ' '.join(ordered_words)

def next_smallest(lst):
    unique_elements = set(lst)
    if len(unique_elements) < 2:
        return None
    sorted_elements = sorted(unique_elements)
    return sorted_elements[1]

def max_fill(grid, capacity):
    total_units = sum(sum(row) for row in grid)
    lowers = total_units // capacity
    if total_units % capacity != 0:
        lowers += 1
    return lowers

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0:
            total += num ** 3
        else:
            total += num
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    return x if is_prime(n) else y

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
